@triton.autotune(configs=[Config({'XBLOCK':256,'YBLOCK':4},...), ...], key=['xnumel','ynumel'])
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: constexpr, XBLOCK: constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    xarange = tl.max_contiguous(tl.multiple_of(xoffset + tl.arange(0, XBLOCK), XBLOCK), XBLOCK)
    xindex = xarange[None, :]  # contiguity hint applied before broadcast
    tmp = tl.load(in_ptr + (x2 + 50176*y3), mask)
    tl.store(out_ptr + (y0 + 3*x2 + 150528*y1), tmp, mask)

